        intSubjectCount = intMaxSubject;

    string strTemplateFile = "MauHtml\\BangDiemToanKhoa_QC99.htm";
    string strFileContent = ReadTemplateFile(strTemplateFile);

    if (strFileContent == null || strFileContent.Length == 0)
    {
        ErrorManager.Error("Không tìm thấy file mẫu HTML: " + strTemplateFile);
        return;
    }

    GetSetting();
    string strBranchLabel = "Chuyên ngành";
    if (uClass.RegulationID == 25)
        strBranchLabel = "Ngành";

    strFileContent = strFileContent.Replace("{REPORT_HEADER_TEXT}", SystemService.SYS_SettingService.GetStringValue("Report_Header_Text"));
    strFileContent = strFileContent.Replace("{REPORT_HEADER2_TEXT}", SystemService.SYS_SettingService.GetStringValue("Report_Header2_Text"));
    strFileContent = strFileContent.Replace("{COURSE}", uClass.CourseName);
    strFileContent = strFileContent.Replace("{TRAINING_LEVEL}", uClass.TrainingLevelName);
    strFileContent = strFileContent.Replace("{SPECIAL_BRANCH}", uClass.SpecialBranchName);
    strFileContent = strFileContent.Replace("{CLASS}", uClass.ClassName);
    strFileContent = strFileContent.Replace("{BRANCH_LABEL}", strBranchLabel);
    strFileContent = strFileContent.Replace("{REPORT_PLACE}", strReport_Place);
    strFileContent = strFileContent.Replace("{TOTAL_STUDENT}", dtbData.Rows.Count.ToString());
    strFileContent = strFileContent.Replace("{TABLE_CONTENT}", BuildToanKhoaTableHTML(intSubjectCount, bolIsTinChi, bolSplitSubjectPages));
    strFileContent = strFileContent.Replace("{STATISTIC}", BuildToanKhoaStatisticHTML());

    string strFilePrefix = bolSplitSubjectPages ? "BangDiemToanKhoa_" : "BangDiemToanKhoa_1Bang_";
    string strFileNameAs = Application.StartupPath + "\\Export\\" + strFilePrefix + uClass.ClassIDEditValue.ToString() + ".htm";
    string strExportDir = Application.StartupPath + "\\Export";
    if (!System.IO.Directory.Exists(strExportDir))
        System.IO.Directory.CreateDirectory(strExportDir);

    System.IO.File.WriteAllText(strFileNameAs, strFileContent, Encoding.UTF8);
    System.Diagnostics.Process.Start(strFileNameAs);
}

