{
    if (strValue == null)
        return "";
    return strValue.Replace("&", "&amp;").Replace("<", "&lt;").Replace(">", "&gt;").Replace("\"", "&quot;");
}

private string FormatStudentCodeHTML(string strCode)
{
    if (strCode == null)
        strCode = "";
    strCode = strCode.Trim();
    if (strCode.Length <= 5)
        return HtmlEncode(strCode);

    string strLine1 = strCode.Substring(0, 5);
    string strLine2 = strCode.Substring(5);
    return HtmlEncode(strLine1) + "<br/>" + HtmlEncode(strLine2);
}

